'use client';

import type { ReactNode } from 'react';
import { ColorPickerContext } from './color-picker-context';
import { useColorPicker, type UseColorPickerOptions } from './use-color-picker';

type ColorPickerProps = UseColorPickerOptions & {
  children: ReactNode;
};

export function ColorPicker({ children, ...options }: ColorPickerProps) {
  const picker = useColorPicker(options);
  return <ColorPickerContext value={picker}>{children}</ColorPickerContext>;
}

'use client';

import { cn } from '@/lib/utils';
import { Button, type ButtonProps } from '../button';
import { colorName } from './color';
import { useColorPickerContext } from './color-picker-context';

type ColorPickerTriggerProps = Omit<ButtonProps, 'ref'>;

/**
 * Swatch plus the hex code. The hex is visible text, not an `aria-label`, so a voice control user
 * can say what they see ("click 3b82f6"); the color name is added for screen readers.
 */
export function ColorPickerTrigger({
  variant = 'outline',
  size,
  loading,
  className,
  children,
  ...props
}: ColorPickerTriggerProps) {
  const { hex, hsv, isOpen, setReference, getReferenceProps } = useColorPickerContext();

  return (
    <Button
      data-slot="color-picker-trigger"
      ref={setReference}
      variant={variant}
      size={size}
      loading={loading}
      data-state={isOpen ? 'open' : 'closed'}
      className={cn('pl-2 data-[state=open]:bg-accent', className)}
      {...getReferenceProps(props)}
    >
      <span
        aria-hidden
        className="size-5 rounded-sm shadow-[inset_0_0_0_1px_rgb(0_0_0/0.12)] transition-[background-color] duration-200 motion-reduce:transition-none dark:shadow-[inset_0_0_0_1px_rgb(255_255_255/0.15)]"
        style={{ backgroundColor: hex }}
      />
      {children}
      <span className="font-mono text-xs text-muted-foreground tabular-nums">{hex}</span>
      <span className="sr-only">, {colorName(hsv)}</span>
    </Button>
  );
}

'use client';

import { FloatingFocusManager } from '@floating-ui/react';
import { AnimatePresence, motion } from 'motion/react';
import type { ReactNode } from 'react';
import { cn } from '@/lib/utils';
import { useColorPickerContext } from './color-picker-context';
import { transformOrigin } from './transform-origin';
import { contentVariants } from './variants';

type ColorPickerContentProps = {
  /** Accessible name of the dialog. */
  label?: string;
  className?: string;
  children: ReactNode;
};

export function ColorPickerContent({
  label = 'Color picker',
  className,
  children,
}: ColorPickerContentProps) {
  const { isOpen, placement, floatingContext, floatingStyles, setFloating, getFloatingProps } =
    useColorPickerContext();

  return (
    <AnimatePresence>
      {isOpen && (
        // Not modal: the page stays reachable, and Tab out or Esc closes it. Focus goes to the area.
        <FloatingFocusManager context={floatingContext} modal={false}>
          <div
            data-slot="color-picker-content"
            ref={setFloating}
            style={floatingStyles}
            aria-label={label}
            className="z-50 outline-none"
            {...getFloatingProps()}
          >
            <motion.div
              variants={contentVariants}
              initial="closed"
              animate="open"
              exit="closed"
              style={{ transformOrigin: transformOrigin(placement) }}
              className={cn(
                'flex w-64 flex-col gap-3 rounded-xl border bg-popover p-3 text-popover-foreground shadow-lg',
                className,
              )}
            >
              {children}
            </motion.div>
          </div>
        </FloatingFocusManager>
      )}
    </AnimatePresence>
  );
}

'use client';

import { motion } from 'motion/react';
import { useRef, type KeyboardEvent } from 'react';
import { cn } from '@/lib/utils';
import { clamp, colorName } from './color';
import { useColorPickerContext } from './color-picker-context';
import { sliderMove } from './slider-keys';
import { usePointerPosition } from './use-pointer-position';
import { useThumbPosition } from './use-thumb-position';
import { partVariants, thumbClassName, thumbPress } from './variants';

type ColorPickerAreaProps = {
  className?: string;
};

/**
 * Saturation (x) and brightness (y). There is no ARIA pattern for a 2D slider, so it's two native
 * range inputs inside the thumb: screen readers can adjust each one (VoiceOver swipes, TalkBack
 * volume keys), and both announce the whole color. Only saturation is in the Tab order; its arrow
 * keys move both axes.
 */
export function ColorPickerArea({ className }: ColorPickerAreaProps) {
  const { hsv, hex, setColor } = useColorPickerContext();
  const saturationRef = useRef<HTMLInputElement>(null);
  const x = useThumbPosition(hsv.s);
  const y = useThumbPosition(1 - hsv.v);

  const { isDragging, pointerProps } = usePointerPosition((position, phase) => {
    x.follow(phase === 'move');
    y.follow(phase === 'move');
    setColor({ ...hsv, s: position.x, v: 1 - position.y });
    if (phase === 'start') saturationRef.current?.focus({ preventScroll: true });
  });

  const onKeyDown = (event: KeyboardEvent) => {
    const move = sliderMove(event, true);
    if (!move) return;
    event.preventDefault();
    x.follow(false);
    y.follow(false);
    const channel = move.axis === 'x' ? 's' : 'v';
    const next =
      'to' in move
        ? Number(move.to === 'max')
        : clamp(Math.round(hsv[channel] * 100 + move.by) / 100);
    setColor({ ...hsv, [channel]: next });
  };

  const saturation = Math.round(hsv.s * 100);
  const brightness = Math.round(hsv.v * 100);
  const name = colorName(hsv);

  return (
    <motion.div
      data-slot="color-picker-area"
      variants={partVariants}
      role="group"
      aria-label="Saturation and brightness"
      onKeyDown={onKeyDown}
      {...pointerProps}
      className={cn(
        'relative h-40 cursor-crosshair touch-none rounded-lg shadow-[inset_0_0_0_1px_rgb(0_0_0/0.08)]',
        className,
      )}
      style={{
        background: `linear-gradient(to top, #000, transparent), linear-gradient(to right, #fff, transparent), hsl(${hsv.h} 100% 50%)`,
      }}
    >
      <motion.div
        data-slot="color-picker-area-thumb"
        className={thumbClassName}
        style={{ left: x.percent, top: y.percent, backgroundColor: hex }}
        animate={{ scale: isDragging ? 1.6 : 1 }}
        transition={thumbPress}
      >
        <input
          ref={saturationRef}
          type="range"
          aria-roledescription="2D slider"
          aria-label="Saturation"
          aria-valuetext={`Saturation ${saturation}%, brightness ${brightness}%, ${name}`}
          min={0}
          max={100}
          value={saturation}
          onChange={(event) => setColor({ ...hsv, s: event.target.valueAsNumber / 100 })}
          className="sr-only"
        />
        <input
          type="range"
          tabIndex={-1}
          aria-roledescription="2D slider"
          aria-label="Brightness"
          aria-valuetext={`Brightness ${brightness}%, saturation ${saturation}%, ${name}`}
          min={0}
          max={100}
          value={brightness}
          onChange={(event) => setColor({ ...hsv, v: event.target.valueAsNumber / 100 })}
          className="sr-only"
        />
      </motion.div>
    </motion.div>
  );
}

'use client';

import { motion } from 'motion/react';
import { useRef, type KeyboardEvent } from 'react';
import { cn } from '@/lib/utils';
import { clamp, hueName } from './color';
import { useColorPickerContext } from './color-picker-context';
import { sliderMove } from './slider-keys';
import { usePointerPosition } from './use-pointer-position';
import { useThumbPosition } from './use-thumb-position';
import { partVariants, thumbClassName, thumbPress } from './variants';

const rainbow =
  'linear-gradient(to right, #f00 0%, #ff0 16.67%, #0f0 33.33%, #0ff 50%, #00f 66.67%, #f0f 83.33%, #f00 100%)';

type ColorPickerHueProps = {
  className?: string;
};

/** A native range input under a custom track, so it's a real slider to every assistive tech. */
export function ColorPickerHue({ className }: ColorPickerHueProps) {
  const { hsv, setColor } = useColorPickerContext();
  const inputRef = useRef<HTMLInputElement>(null);
  const x = useThumbPosition(hsv.h / 360);

  const { isDragging, pointerProps } = usePointerPosition((position, phase) => {
    x.follow(phase === 'move');
    setColor({ ...hsv, h: position.x * 360 });
    if (phase === 'start') inputRef.current?.focus({ preventScroll: true });
  });

  const onKeyDown = (event: KeyboardEvent) => {
    const move = sliderMove(event, false);
    if (!move) return;
    event.preventDefault();
    x.follow(false);
    const h =
      'to' in move ? (move.to === 'max' ? 360 : 0) : clamp(Math.round(hsv.h) + move.by, 0, 360);
    setColor({ ...hsv, h });
  };

  const hue = Math.round(hsv.h);

  return (
    <motion.div
      data-slot="color-picker-hue"
      variants={partVariants}
      onKeyDown={onKeyDown}
      {...pointerProps}
      className={cn(
        'relative h-3 flex-1 cursor-pointer touch-none rounded-full shadow-[inset_0_0_0_1px_rgb(0_0_0/0.08)]',
        className,
      )}
      style={{ background: rainbow }}
    >
      <motion.div
        data-slot="color-picker-hue-thumb"
        className={cn(thumbClassName, 'top-1/2')}
        style={{ left: x.percent, backgroundColor: `hsl(${hsv.h} 100% 50%)` }}
        animate={{ scale: isDragging ? 1.4 : 1 }}
        transition={thumbPress}
      >
        <input
          ref={inputRef}
          type="range"
          aria-label="Hue"
          aria-valuetext={`${hue} degrees, ${hueName(hsv.h)}`}
          min={0}
          max={360}
          value={hue}
          onChange={(event) => setColor({ ...hsv, h: event.target.valueAsNumber })}
          className="sr-only"
        />
      </motion.div>
    </motion.div>
  );
}

'use client';

import { Composite, CompositeItem } from '@floating-ui/react';
import { AnimatePresence, motion } from 'motion/react';
import { useId, useRef, useState, type KeyboardEvent } from 'react';
import { cn } from '@/lib/utils';
import { colorName, contrastingText, hexToHsv, parseHex } from './color';
import { useColorPickerContext } from './color-picker-context';
import { partVariants, thumbJump, thumbPress } from './variants';

const navigationKeys = ['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown', 'Home', 'End'];

type ColorPickerSwatchesProps = {
  /** Hex colors. */
  colors: string[];
  columns?: number;
  label?: string;
  className?: string;
};

/**
 * Preset colors as a radio group: Tab lands on the selected one, arrows move and select (roving
 * focus from Floating UI's Composite), and the selection ring slides to the new swatch.
 */
export function ColorPickerSwatches({
  colors,
  columns = 8,
  label = 'Swatches',
  className,
}: ColorPickerSwatchesProps) {
  const { hex, setHex } = useColorPickerContext();
  const ringId = useId();
  const swatches = colors.map((color) => parseHex(color) ?? color);
  const selectedIndex = swatches.indexOf(hex);

  const [activeIndex, setActiveIndex] = useState(Math.max(selectedIndex, 0));
  const [prevSelectedIndex, setPrevSelectedIndex] = useState(selectedIndex);
  if (selectedIndex !== prevSelectedIndex) {
    setPrevSelectedIndex(selectedIndex);
    if (selectedIndex !== -1) setActiveIndex(selectedIndex);
  }

  // Composite also navigates on focus (Tab in); only a navigation key should pick a color.
  const isKeyNavigation = useRef(false);

  return (
    <motion.div variants={partVariants}>
      <Composite
        data-slot="color-picker-swatches"
        role="radiogroup"
        aria-label={label}
        orientation="both"
        cols={columns}
        loop
        activeIndex={activeIndex}
        onNavigate={(index) => {
          setActiveIndex(index);
          if (isKeyNavigation.current) setHex(swatches[index]);
          isKeyNavigation.current = false;
        }}
        onKeyDown={(event: KeyboardEvent) => {
          isKeyNavigation.current = navigationKeys.includes(event.key);
        }}
        className={cn('grid gap-1.5', className)}
        style={{ gridTemplateColumns: `repeat(${columns}, minmax(0, 1fr))` }}
      >
        {swatches.map((swatch) => {
          const isSelected = swatch === hex;
          return (
            <CompositeItem
              key={swatch}
              render={
                <button
                  type="button"
                  data-slot="color-picker-swatch"
                  role="radio"
                  aria-checked={isSelected}
                  aria-label={`${colorName(hexToHsv(swatch))}, ${swatch}`}
                  onClick={() => setHex(swatch)}
                  className="group relative aspect-square cursor-pointer rounded-md outline-none"
                />
              }
            >
              {/* CSS, not whileTap: Motion makes tap targets focusable, which adds a Tab stop. */}
              <span
                aria-hidden
                className={cn(
                  'absolute inset-0 flex items-center justify-center rounded-md shadow-[inset_0_0_0_1px_rgb(0_0_0/0.1)] dark:shadow-[inset_0_0_0_1px_rgb(255_255_255/0.12)]',
                  'transition-[scale] duration-200 ease-[cubic-bezier(0.3,1.6,0.5,1)] group-hover:scale-110 group-active:scale-85 motion-reduce:transition-none',
                  'group-focus-visible:ring-[3px] group-focus-visible:ring-ring/50',
                )}
                style={{ backgroundColor: swatch, color: contrastingText(swatch) }}
              >
                <AnimatePresence initial={false}>
                  {isSelected && (
                    <motion.svg
                      key="check"
                      viewBox="0 0 24 24"
                      fill="none"
                      stroke="currentColor"
                      strokeWidth="3.5"
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      className="size-3"
                      initial={{ opacity: 0, scale: 0.4 }}
                      animate={{ opacity: 1, scale: 1 }}
                      exit={{ opacity: 0, scale: 0.4 }}
                      transition={thumbPress}
                    >
                      <motion.path
                        d="M20 6 9 17l-5-5"
                        initial={{ pathLength: 0 }}
                        animate={{ pathLength: 1 }}
                        transition={{ duration: 0.2, ease: 'easeOut', delay: 0.05 }}
                      />
                    </motion.svg>
                  )}
                </AnimatePresence>
              </span>
              {isSelected && (
                <motion.span
                  layoutId={ringId}
                  aria-hidden
                  transition={thumbJump}
                  className="pointer-events-none absolute -inset-[3px] rounded-[9px] border-2 border-foreground/80"
                />
              )}
            </CompositeItem>
          );
        })}
      </Composite>
    </motion.div>
  );
}

'use client';

import { motion, useAnimate, useReducedMotion } from 'motion/react';
import { useId, useState, type FormEvent } from 'react';
import { cn } from '@/lib/utils';
import { parseHex } from './color';
import { useColorPickerContext } from './color-picker-context';
import { partVariants, shakeKeyframes, shakeTransition } from './variants';

type ColorPickerInputProps = {
  label?: string;
  className?: string;
};

/**
 * Hex field. A full `rrggbb` applies while typing; `rgb` shorthand applies on Enter or blur.
 * Anything invalid shakes, is announced, and goes back to the current color.
 */
export function ColorPickerInput({ label = 'Hex', className }: ColorPickerInputProps) {
  const { hex, setHex } = useColorPickerContext();
  const id = useId();
  const [scope, animate] = useAnimate<HTMLDivElement>();
  const shouldReduceMotion = useReducedMotion();
  const [draft, setDraft] = useState(hex.slice(1));
  const [isEditing, setIsEditing] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Follow changes made elsewhere (area, swatches), but never overwrite what's being typed.
  const [prevHex, setPrevHex] = useState(hex);
  if (hex !== prevHex) {
    setPrevHex(hex);
    if (!isEditing) setDraft(hex.slice(1));
  }

  const onChange = (event: FormEvent<HTMLInputElement>) => {
    const next = event.currentTarget.value.replace(/^#/, '');
    setDraft(next);
    setError(null);
    const parsed = next.length === 6 ? parseHex(next) : null;
    if (parsed) setHex(parsed);
  };

  const commit = () => {
    const parsed = parseHex(draft);
    if (parsed) {
      setHex(parsed);
      setDraft(parsed.slice(1));
      return;
    }
    setError(`${draft || 'Empty'} isn't a hex color. Kept ${hex}.`);
    setDraft(hex.slice(1));
    if (!shouldReduceMotion) animate(scope.current, shakeKeyframes, shakeTransition);
  };

  return (
    <motion.div variants={partVariants} className={cn('flex flex-col gap-1', className)}>
      <div ref={scope} className="flex items-center gap-2">
        <label htmlFor={id} className="text-xs font-medium text-muted-foreground">
          {label}
        </label>
        <div
          className={cn(
            'flex h-8 flex-1 items-center rounded-md border bg-background px-2 font-mono text-xs shadow-xs transition-[box-shadow,border-color] duration-150',
            'focus-within:border-ring focus-within:ring-[3px] focus-within:ring-ring/50',
            error && 'border-destructive ring-[3px] ring-destructive/20',
          )}
        >
          <span aria-hidden className="text-muted-foreground">
            #
          </span>
          <input
            id={id}
            data-slot="color-picker-input"
            value={draft}
            onChange={onChange}
            onFocus={(event) => {
              setIsEditing(true);
              event.currentTarget.select();
            }}
            onBlur={() => {
              setIsEditing(false);
              commit();
            }}
            onKeyDown={(event) => {
              if (event.key === 'Enter') commit();
            }}
            maxLength={7}
            spellCheck={false}
            autoComplete="off"
            aria-invalid={error !== null || undefined}
            aria-describedby={`${id}-error`}
            className="w-full min-w-0 bg-transparent pl-0.5 tabular-nums outline-none"
          />
        </div>
      </div>
      <p id={`${id}-error`} aria-live="polite" className="sr-only">
        {error}
      </p>
    </motion.div>
  );
}

'use client';

import { AnimatePresence, motion } from 'motion/react';
import { useState } from 'react';
import { cn } from '@/lib/utils';
import { IconButton } from '../icon-button';
import { parseHex } from './color';
import { useColorPickerContext } from './color-picker-context';
import { EyeDropperIcon } from './icons';
import { useEyeDropper } from './use-eye-dropper';
import { partVariants } from './variants';

type ColorPickerEyeDropperProps = {
  className?: string;
};

/** Picks a color from anywhere on screen. Renders nothing where the EyeDropper API is missing. */
export function ColorPickerEyeDropper({ className }: ColorPickerEyeDropperProps) {
  const { setHex } = useColorPickerContext();
  const pick = useEyeDropper();
  // Each pick ripples out in the picked color; the key restarts the ripple.
  const [picked, setPicked] = useState<{ hex: string; key: number } | null>(null);

  if (!pick) return null;

  const onClick = async () => {
    const hex = parseHex((await pick()) ?? '');
    if (!hex) return;
    setHex(hex);
    setPicked((prev) => ({ hex, key: (prev?.key ?? 0) + 1 }));
  };

  return (
    <motion.div variants={partVariants} className="relative">
      <IconButton
        data-slot="color-picker-eye-dropper"
        label="Pick a color from the screen"
        variant="ghost"
        size="sm"
        onClick={onClick}
        className={cn('text-muted-foreground', className)}
      >
        <EyeDropperIcon />
      </IconButton>
      <AnimatePresence>
        {picked && (
          <motion.span
            key={picked.key}
            aria-hidden
            initial={{ scale: 0.6, opacity: 0.8 }}
            animate={{ scale: 1.6, opacity: 0 }}
            transition={{ duration: 0.6, ease: 'easeOut' }}
            onAnimationComplete={() => setPicked(null)}
            className="pointer-events-none absolute inset-0 rounded-full"
            style={{ boxShadow: `0 0 0 3px ${picked.hex}` }}
          />
        )}
      </AnimatePresence>
      <span aria-live="polite" className="sr-only">
        {picked ? `Picked ${picked.hex}` : ''}
      </span>
    </motion.div>
  );
}

import {
  autoUpdate,
  flip,
  offset,
  shift,
  useClick,
  useDismiss,
  useFloating,
  useInteractions,
  useRole,
  type Placement,
} from '@floating-ui/react';
import { useState } from 'react';
import { hexToHsv, hsvToHex, parseHex, type Hsv } from './color';

export type UseColorPickerOptions = {
  /** Hex color (`#rrggbb`). Pass it to control the picker. */
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  placement?: Placement;
};

/**
 * Color state plus the popover. The color lives as HSV so hue survives grays and black (a hex has
 * no hue there), and the area and hue slider don't jump while you drag through them.
 */
export function useColorPicker({
  value,
  defaultValue = '#000000',
  onValueChange,
  placement = 'bottom-start',
}: UseColorPickerOptions) {
  const [isOpen, setIsOpen] = useState(false);
  const [hsv, setHsv] = useState<Hsv>(() => hexToHsv(parseHex(value ?? defaultValue) ?? '#000000'));
  const hex = hsvToHex(hsv);

  // Controlled: take a new `value` from the parent, unless it's the color we already show.
  const [prevValue, setPrevValue] = useState(value);
  if (value !== prevValue) {
    setPrevValue(value);
    const parsed = value === undefined ? null : parseHex(value);
    if (parsed && parsed !== hex) setHsv(hexToHsv(parsed, hsv.h));
  }

  const setColor = (next: Hsv) => {
    setHsv(next);
    const nextHex = hsvToHex(next);
    if (nextHex !== hex) onValueChange?.(nextHex);
  };

  const setHex = (next: string) => setColor(hexToHsv(next, hsv.h));

  const floating = useFloating({
    open: isOpen,
    onOpenChange: setIsOpen,
    placement,
    // Same as the dropdown menu: fixed and rendered in place, so it escapes `overflow: hidden`.
    strategy: 'fixed',
    middleware: [offset(8), flip({ padding: 8 }), shift({ padding: 8 })],
    whileElementsMounted: autoUpdate,
  });

  const interactions = useInteractions([
    useClick(floating.context),
    useRole(floating.context, { role: 'dialog' }),
    useDismiss(floating.context),
  ]);

  return {
    ...interactions,
    hsv,
    hex,
    setColor,
    setHex,
    isOpen,
    setIsOpen,
    placement: floating.placement,
    floatingContext: floating.context,
    floatingStyles: floating.floatingStyles,
    setReference: floating.refs.setReference,
    setFloating: floating.refs.setFloating,
  };
}

export type ColorPickerState = ReturnType<typeof useColorPicker>;

import { useState, type PointerEvent } from 'react';
import { clamp } from './color';

export type PointerPhase = 'start' | 'move';

/**
 * Reports where the pointer is inside the element, as fractions (0–1) of its width and height.
 * Pointer capture keeps the drag going outside the element, and the thumb pinned to its edge.
 */
export function usePointerPosition(
  onPosition: (position: { x: number; y: number }, phase: PointerPhase) => void,
) {
  const [isDragging, setIsDragging] = useState(false);

  const report = (event: PointerEvent<HTMLElement>, phase: PointerPhase) => {
    const rect = event.currentTarget.getBoundingClientRect();
    onPosition(
      {
        x: clamp((event.clientX - rect.left) / rect.width),
        y: clamp((event.clientY - rect.top) / rect.height),
      },
      phase,
    );
  };

  const pointerProps = {
    onPointerDown: (event: PointerEvent<HTMLElement>) => {
      if (event.button !== 0) return;
      // No mousedown follows, so focus doesn't leave the slider's input and no text gets selected.
      event.preventDefault();
      event.currentTarget.setPointerCapture(event.pointerId);
      setIsDragging(true);
      report(event, 'start');
    },
    onPointerMove: (event: PointerEvent<HTMLElement>) => {
      if (event.currentTarget.hasPointerCapture(event.pointerId)) report(event, 'move');
    },
    onLostPointerCapture: () => setIsDragging(false),
  };

  return { isDragging, pointerProps };
}

import { animate, useMotionValue, useReducedMotion, useTransform } from 'motion/react';
import { useEffect, useRef } from 'react';
import { thumbFollow, thumbJump } from './variants';

/**
 * A thumb position (0–1) as a CSS percentage that springs to each new value: with a small overshoot
 * after a jump, tightly while dragging. `follow()` marks the next change as part of a drag.
 */
export function useThumbPosition(value: number) {
  const position = useMotionValue(value);
  const isFollowing = useRef(false);
  const shouldReduceMotion = useReducedMotion();

  useEffect(() => {
    if (shouldReduceMotion) {
      position.jump(value);
    } else {
      const controls = animate(position, value, isFollowing.current ? thumbFollow : thumbJump);
      return () => controls.stop();
    }
  }, [value, position, shouldReduceMotion]);

  return {
    percent: useTransform(position, (fraction) => `${fraction * 100}%`),
    follow: (isDrag: boolean) => {
      isFollowing.current = isDrag;
    },
  };
}

import { useSyncExternalStore } from 'react';

type EyeDropperConstructor = new () => { open: () => Promise<{ sRGBHex: string }> };

const getEyeDropper = () =>
  (globalThis as { EyeDropper?: EyeDropperConstructor }).EyeDropper ?? null;

const subscribe = () => () => {};

/**
 * The EyeDropper API (Chromium only for now). `null` on the server and where it's missing, so the
 * button only renders where it works.
 */
export function useEyeDropper() {
  const EyeDropper = useSyncExternalStore(subscribe, getEyeDropper, () => null);
  if (!EyeDropper) return null;

  /** Resolves with the picked hex, or null when the user cancels with Esc. */
  return async () => {
    try {
      const { sRGBHex } = await new EyeDropper().open();
      return sRGBHex;
    } catch {
      return null;
    }
  };
}

import type { KeyboardEvent } from 'react';

export type SliderMove = { axis: 'x' | 'y'; by: number } | { axis: 'x' | 'y'; to: 'min' | 'max' };

/**
 * Keys of the WAI-ARIA slider pattern, in steps: arrows move 1 (10 with Shift), Page Up/Down 10,
 * Home/End to the ends. On a 2D area, left/right is x and up/down is y; on a 1D slider every key
 * moves x. `y` grows upwards, like brightness.
 */
export function sliderMove(event: KeyboardEvent, is2d: boolean): SliderMove | null {
  const step = event.shiftKey ? 10 : 1;
  const vertical = is2d ? 'y' : 'x';

  switch (event.key) {
    case 'ArrowRight':
      return { axis: 'x', by: step };
    case 'ArrowLeft':
      return { axis: 'x', by: -step };
    case 'ArrowUp':
      return { axis: vertical, by: step };
    case 'ArrowDown':
      return { axis: vertical, by: -step };
    case 'PageUp':
      return { axis: vertical, by: 10 };
    case 'PageDown':
      return { axis: vertical, by: -10 };
    case 'Home':
      return { axis: 'x', to: 'min' };
    case 'End':
      return { axis: 'x', to: 'max' };
    default:
      return null;
  }
}

/** Hue in degrees (0–360), saturation and value (brightness) in 0–1. */
export type Hsv = { h: number; s: number; v: number };

export const clamp = (value: number, min = 0, max = 1) => Math.min(max, Math.max(min, value));

export function hsvToRgb({ h, s, v }: Hsv): [number, number, number] {
  const f = (n: number) => {
    const k = (n + h / 60) % 6;
    return v - v * s * Math.max(0, Math.min(k, 4 - k, 1));
  };
  return [f(5), f(3), f(1)].map((channel) => Math.round(channel * 255)) as [number, number, number];
}

export function hsvToHex(hsv: Hsv) {
  return `#${hsvToRgb(hsv)
    .map((channel) => channel.toString(16).padStart(2, '0'))
    .join('')}`;
}

/** `#rgb` or `#rrggbb`, with or without the `#`. Anything else is null. */
export function parseHex(input: string) {
  const hex = input.trim().replace(/^#/, '').toLowerCase();
  if (!/^([0-9a-f]{3}|[0-9a-f]{6})$/.test(hex)) return null;
  const full = hex.length === 3 ? [...hex].map((char) => char + char).join('') : hex;
  return `#${full}`;
}

/** `hue` is kept when the color has none (grays), so the hue slider doesn't jump back to red. */
export function hexToHsv(hex: string, hue = 0): Hsv {
  const [r, g, b] = [1, 3, 5].map((i) => parseInt(hex.slice(i, i + 2), 16) / 255);
  const max = Math.max(r, g, b);
  const delta = max - Math.min(r, g, b);

  let h = hue;
  if (delta > 0) {
    if (max === r) h = 60 * (((g - b) / delta + 6) % 6);
    else if (max === g) h = 60 * ((b - r) / delta + 2);
    else h = 60 * ((r - g) / delta + 4);
  }
  return { h, s: max === 0 ? 0 : delta / max, v: max };
}

/** Black or white, whichever reads better on top of `hex` (WCAG relative luminance). */
export function contrastingText(hex: string) {
  const [r, g, b] = [1, 3, 5].map((i) => {
    const channel = parseInt(hex.slice(i, i + 2), 16) / 255;
    return channel <= 0.04045 ? channel / 12.92 : ((channel + 0.055) / 1.055) ** 2.4;
  });
  const luminance = 0.2126 * r + 0.7152 * g + 0.0722 * b;
  return luminance > 0.179 ? '#000000' : '#ffffff';
}

const hueNames: Array<[limit: number, name: string]> = [
  [15, 'red'],
  [40, 'orange'],
  [65, 'yellow'],
  [90, 'lime'],
  [150, 'green'],
  [185, 'teal'],
  [200, 'cyan'],
  [250, 'blue'],
  [280, 'violet'],
  [320, 'purple'],
  [345, 'pink'],
  [360, 'red'],
];

export function hueName(hue: number) {
  return hueNames.find(([limit]) => hue < limit)?.[1] ?? 'red';
}

/**
 * Plain-language name ("dark muted blue"), so a screen reader says something more useful than
 * three numbers. Approximate on purpose: it describes, it doesn't identify.
 */
export function colorName({ h, s, v }: Hsv) {
  const lightness = v * (1 - s / 2);
  const saturation =
    lightness === 0 || lightness === 1 ? 0 : (v - lightness) / Math.min(lightness, 1 - lightness);

  if (lightness < 0.08) return 'black';
  if (lightness > 0.96 && saturation < 0.3) return 'white';
  const tone = lightness < 0.35 ? 'dark ' : lightness > 0.75 ? 'light ' : '';
  if (saturation < 0.12) return `${tone}gray`;
  const chroma = saturation < 0.4 ? 'muted ' : saturation > 0.85 && tone === '' ? 'vivid ' : '';
  return `${tone}${chroma}${hueName(h)}`;
}

import type { Transition, Variants } from 'motion/react';

// Grows out of the trigger like the dropdown menu; the parts follow in a short cascade.
export const contentVariants: Variants = {
  closed: { opacity: 0, scale: 0.94, transition: { duration: 0.12, ease: 'easeIn' } },
  open: {
    opacity: 1,
    scale: 1,
    transition: { type: 'spring', duration: 0.3, bounce: 0.1, staggerChildren: 0.03 },
  },
};

/** On a part's root, so it joins the content's cascade. */
export const partVariants: Variants = {
  closed: { opacity: 0, y: 4, filter: 'blur(2px)', transition: { duration: 0.1 } },
  open: { opacity: 1, y: 0, filter: 'blur(0px)', transition: { duration: 0.2, ease: 'easeOut' } },
};

/** A jump (click on the track, a key press) lands with a little overshoot. */
export const thumbJump: Transition = { type: 'spring', duration: 0.35, bounce: 0.25 };
/** While dragging, the thumb stays glued to the pointer, just smoothed. */
export const thumbFollow: Transition = { type: 'spring', stiffness: 1400, damping: 80 };

/** The thumb swells under the finger, so you can see the color you're on. */
export const thumbPress: Transition = { type: 'spring', duration: 0.25, bounce: 0.4 };

export const shakeKeyframes = { x: [0, -5, 5, -3, 3, 0] };
export const shakeTransition: Transition = { duration: 0.4, ease: 'easeInOut' };

export const thumbClassName = [
  'pointer-events-none absolute size-4 -translate-1/2 rounded-full',
  'shadow-[0_0_0_2px_white,0_0_0_3px_rgb(0_0_0/0.2),0_2px_6px_rgb(0_0_0/0.25)]',
  'has-[input:focus-visible]:shadow-[0_0_0_2px_white,0_0_0_5px_var(--color-ring),0_2px_6px_rgb(0_0_0/0.25)]',
].join(' ');

import type { Placement } from '@floating-ui/react';

const alignX = { start: 'left', end: 'right' } as const;
const alignY = { start: 'top', end: 'bottom' } as const;

/** The corner or edge touching the trigger, so the popover grows out of it (also after a flip). */
export function transformOrigin(placement: Placement) {
  const [side, align] = placement.split('-') as [string, 'start' | 'end' | undefined];

  if (side === 'top' || side === 'bottom') {
    return `${align ? alignX[align] : 'center'} ${side === 'bottom' ? 'top' : 'bottom'}`;
  }
  return `${side === 'right' ? 'left' : 'right'} ${align ? alignY[align] : 'center'}`;
}

'use client';

import { createContext, useContext } from 'react';
import type { ColorPickerState } from './use-color-picker';

export const ColorPickerContext = createContext<ColorPickerState | null>(null);

export function useColorPickerContext() {
  const context = useContext(ColorPickerContext);
  if (!context) throw new Error('ColorPicker parts must be rendered inside <ColorPicker>.');
  return context;
}
